//! Closed source inventory for recursion in the association implementation roots.
//!
//! The scan intentionally matches the layer-3 implementation boundary. It sees
//! direct calls and `self`/`Self` method calls whose caller and callee are
//! defined in the same file. These roots implement the catalog association
//! surface and its six declared cross-family axes; that correspondence, rather
//! than convenience, defines the boundary. The scan cannot see recursion
//! reached through a trait object or function pointer, recursion generated by
//! a macro, or recursion outside [`SCANNED_ROOTS`].

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};

use syn::visit::{self, Visit};
use syn::{Expr, ExprCall, ExprMethodCall, ImplItemFn, ItemFn, Type};

use super::{DeclaredRecursiveEdge, RecursiveEdge};

pub(super) const SCANNED_ROOTS: &[&str] = &[
    "crates/rum-runtime/src/runtime/kernel_data/association_data.rs",
    "crates/rum-runtime/src/runtime/kernel_data/structure_data/exact_paths.rs",
    "crates/rum-stdlib/src/associations",
    "crates/rum-stdlib/src/functional_ops/apply_map",
];

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum CallableKind {
    Free,
    Method { owner: String },
}

#[derive(Clone)]
struct Callable<'ast> {
    name: String,
    kind: CallableKind,
    block: &'ast syn::Block,
}

#[derive(Default)]
struct CallableCollector<'ast> {
    callables: Vec<Callable<'ast>>,
    current_impl: Option<String>,
}

impl<'ast> Visit<'ast> for CallableCollector<'ast> {
    fn visit_item_fn(&mut self, function: &'ast ItemFn) {
        self.callables.push(Callable {
            name: function.sig.ident.to_string(),
            kind: CallableKind::Free,
            block: &function.block,
        });
        visit::visit_item_fn(self, function);
    }

    fn visit_item_impl(&mut self, implementation: &'ast syn::ItemImpl) {
        let previous = self
            .current_impl
            .replace(type_name(&implementation.self_ty));
        visit::visit_item_impl(self, implementation);
        self.current_impl = previous;
    }

    fn visit_impl_item_fn(&mut self, function: &'ast ImplItemFn) {
        let owner = self
            .current_impl
            .clone()
            .expect("an impl method should be visited inside its impl");
        self.callables.push(Callable {
            name: format!("{owner}::{}", function.sig.ident),
            kind: CallableKind::Method { owner },
            block: &function.block,
        });
        visit::visit_impl_item_fn(self, function);
    }
}

fn type_name(ty: &Type) -> String {
    match ty {
        Type::Path(path) => path
            .path
            .segments
            .iter()
            .map(|segment| segment.ident.to_string())
            .collect::<Vec<_>>()
            .join("::"),
        Type::Reference(reference) => type_name(&reference.elem),
        _ => "<impl>".to_string(),
    }
}

struct CallCollector<'a> {
    caller: &'a Callable<'a>,
    free_names: &'a BTreeMap<String, Vec<String>>,
    method_names: &'a BTreeSet<String>,
    counts: BTreeMap<String, usize>,
}

impl CallCollector<'_> {
    fn record(&mut self, callee: String) {
        *self.counts.entry(callee).or_default() += 1;
    }

    fn resolve_call(&self, call: &ExprCall) -> Option<String> {
        let Expr::Path(path) = call.func.as_ref() else {
            return None;
        };
        let segments = path.path.segments.iter().collect::<Vec<_>>();
        let callee = segments.last()?.ident.to_string();

        if segments.len() >= 2 && segments[segments.len() - 2].ident == "Self" {
            if let CallableKind::Method { owner } = &self.caller.kind {
                let qualified = format!("{owner}::{callee}");
                return self.method_names.contains(&qualified).then_some(qualified);
            }
        }

        let candidates = self.free_names.get(&callee)?;
        (candidates.len() == 1).then(|| candidates[0].clone())
    }
}

impl<'ast> Visit<'ast> for CallCollector<'_> {
    fn visit_expr_call(&mut self, call: &'ast ExprCall) {
        if let Some(callee) = self.resolve_call(call) {
            self.record(callee);
        }
        visit::visit_expr_call(self, call);
    }

    fn visit_expr_method_call(&mut self, call: &'ast ExprMethodCall) {
        if matches!(call.receiver.as_ref(), Expr::Path(path) if path.path.is_ident("self")) {
            if let CallableKind::Method { owner } = &self.caller.kind {
                let qualified = format!("{owner}::{}", call.method);
                if self.method_names.contains(&qualified) {
                    self.record(qualified);
                }
            }
        }
        visit::visit_expr_method_call(self, call);
    }
}

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .expect("stdlib crate should live under the workspace crates directory")
        .to_path_buf()
}

fn relative_source(workspace: &Path, path: &Path) -> String {
    path.strip_prefix(workspace)
        .expect("scanned source should be inside the workspace")
        .display()
        .to_string()
        .replace('\\', "/")
}

fn collect_rust_sources(path: &Path, files: &mut Vec<PathBuf>) {
    if path.is_dir() {
        let mut entries = fs::read_dir(path)
            .expect("recursion inventory should read its source roots")
            .map(|entry| {
                entry
                    .expect("recursion inventory should read source entries")
                    .path()
            })
            .collect::<Vec<_>>();
        entries.sort();
        for entry in entries {
            collect_rust_sources(&entry, files);
        }
    } else if path.extension().and_then(|extension| extension.to_str()) == Some("rs") {
        files.push(path.to_path_buf());
    }
}

fn reaches(graph: &BTreeMap<String, BTreeSet<String>>, start: &str, target: &str) -> bool {
    let mut pending = vec![start.to_string()];
    let mut visited = BTreeSet::new();
    while let Some(node) = pending.pop() {
        if node == target {
            return true;
        }
        if !visited.insert(node.clone()) {
            continue;
        }
        if let Some(next) = graph.get(&node) {
            pending.extend(next.iter().rev().cloned());
        }
    }
    false
}

fn recursive_edges_from_source(path: &str, source: &str) -> Vec<RecursiveEdge> {
    let syntax = syn::parse_file(source)
        .unwrap_or_else(|error| panic!("recursion inventory should parse {path}: {error}"));
    let mut definitions = CallableCollector::default();
    definitions.visit_file(&syntax);
    definitions
        .callables
        .sort_by(|left, right| left.name.cmp(&right.name));
    assert!(
        definitions
            .callables
            .windows(2)
            .all(|callables| callables[0].name != callables[1].name),
        "recursion inventory found ambiguous same-file callable names in {path}"
    );

    let mut free_names = BTreeMap::<String, Vec<String>>::new();
    let mut method_names = BTreeSet::new();
    for callable in &definitions.callables {
        match &callable.kind {
            CallableKind::Free => free_names
                .entry(callable.name.clone())
                .or_default()
                .push(callable.name.clone()),
            CallableKind::Method { .. } => {
                method_names.insert(callable.name.clone());
            }
        }
    }

    let mut calls = BTreeMap::<(String, String), usize>::new();
    for caller in &definitions.callables {
        let mut collector = CallCollector {
            caller,
            free_names: &free_names,
            method_names: &method_names,
            counts: BTreeMap::new(),
        };
        collector.visit_block(caller.block);
        for (callee, count) in collector.counts {
            calls.insert((caller.name.clone(), callee), count);
        }
    }

    let mut graph = BTreeMap::<String, BTreeSet<String>>::new();
    for ((caller, callee), _) in &calls {
        graph
            .entry(caller.clone())
            .or_default()
            .insert(callee.clone());
    }

    calls
        .into_iter()
        .filter(|((caller, callee), _)| reaches(&graph, callee, caller))
        .map(|((caller, callee), count)| RecursiveEdge {
            path: path.to_string(),
            caller,
            callee,
            count,
        })
        .collect()
}

pub(super) fn production_recursive_edges() -> Vec<RecursiveEdge> {
    let workspace = workspace_root();
    let mut files = Vec::new();
    for root in SCANNED_ROOTS {
        collect_rust_sources(&workspace.join(root), &mut files);
    }
    files.sort();
    files.dedup();

    let mut edges = files
        .iter()
        .flat_map(|path| {
            let relative = relative_source(&workspace, path);
            let source = fs::read_to_string(path).unwrap_or_else(|error| {
                panic!("recursion inventory should read {relative}: {error}")
            });
            recursive_edges_from_source(&relative, &source)
        })
        .collect::<Vec<_>>();
    edges.sort();
    edges
}

