fn expected_declared_production_recursion() -> Vec<DeclaredRecursiveEdge> {
    EXPECTED_RECURSION
        .iter()
        .map(
            |(path, caller, callee, count, declaration)| DeclaredRecursiveEdge {
                edge: RecursiveEdge {
                    path: (*path).to_string(),
                    caller: (*caller).to_string(),
                    callee: (*callee).to_string(),
                    count: *count,
                },
                declaration,
            },
        )
        .collect()
}

pub(super) fn declared_production_recursion() -> Vec<DeclaredRecursiveEdge> {
    let expected = expected_declared_production_recursion()
        .into_iter()
        .map(|row| (row.edge, row.declaration))
        .collect::<BTreeMap<_, _>>();

    production_recursive_edges()
        .into_iter()
        .map(|edge| DeclaredRecursiveEdge {
            declaration: expected.get(&edge).copied().unwrap_or("<unregistered>"),
            edge,
        })
        .collect()
}

fn format_edges(edges: &[RecursiveEdge]) -> String {
    edges
        .iter()
        .map(|edge| {
            format!(
                "({:?}, {:?}, {:?}, {})",
                edge.path, edge.caller, edge.callee, edge.count
            )
        })
        .collect::<Vec<_>>()
        .join("\n")
}

#[test]
fn association_recursion_inventory_is_sorted_exhaustive_and_declared() {
    assert!(
        EXPECTED_RECURSION.windows(2).all(|rows| rows[0] < rows[1]),
        "the association recursion inventory must stay sorted and unique"
    );

    let actual = production_recursive_edges();
    let expected = expected_declared_production_recursion()
        .into_iter()
        .map(|row| row.edge)
        .collect::<Vec<_>>();
    let actual_set = actual.iter().cloned().collect::<BTreeSet<_>>();
    let expected_set = expected.iter().cloned().collect::<BTreeSet<_>>();
    let unexpected = actual_set
        .difference(&expected_set)
        .cloned()
        .collect::<Vec<_>>();
    let missing = expected_set
        .difference(&actual_set)
        .cloned()
        .collect::<Vec<_>>();

    assert!(
        unexpected.is_empty() && missing.is_empty(),
        "association recursion inventory mismatch\nunexpected recursive edges:\n{}\nmissing recursive edges:\n{}",
        format_edges(&unexpected),
        format_edges(&missing)
    );
}

#[test]
fn synthetic_unregistered_recursion_is_reported_exactly() {
    let source = r#"
        fn self_recursive() { self_recursive(); }
        fn mutual_left() { mutual_right(); mutual_right(); }
        fn mutual_right() { mutual_left(); }
        fn acyclic_root() { acyclic_leaf(); }
        fn acyclic_leaf() {}
    "#;

    assert_eq!(
        recursive_edges_from_source("synthetic.rs", source),
        vec![
            RecursiveEdge {
                path: "synthetic.rs".to_string(),
                caller: "mutual_left".to_string(),
                callee: "mutual_right".to_string(),
                count: 2,
            },
            RecursiveEdge {
                path: "synthetic.rs".to_string(),
                caller: "mutual_right".to_string(),
                callee: "mutual_left".to_string(),
                count: 1,
            },
            RecursiveEdge {
                path: "synthetic.rs".to_string(),
                caller: "self_recursive".to_string(),
                callee: "self_recursive".to_string(),
                count: 1,
            },
        ]
    );
}
